INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('이쓰쿠시마 신사', '嚴島神社', 'SHRINE_TEMPLE', '広島県', '廿日市市', 34.296000, 132.319800, 'FIXED', '06:30', '18:00', NULL, '3/1~10/14 기준. 10/15~11/30·1/4~2월 말 17:30, 12월 17:00, 1/1 0:00~18:30, 1/2~1/3 18:30까지', '승전료 300엔 (미야지마 방문세 100엔 별도)', '593년 창건으로 전해지는 바다 위의 신사. 평청성이 조영한 사전과 바다 속 대도리이로 유명한 세계유산이다.', '오층탑 보수가 2026년 12월 20일까지 이어진다. 가을·겨울엔 폐문이 빨라지니 늦은 오후 참배는 주의.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('히로시마 평화기념공원', '平和記念公園', 'PARK_GARDEN', '広島県', '広島市中区', 34.392600, 132.452300, 'ALWAYS', NULL, NULL, NULL, '상시 개방, 무휴', '무료', '원폭 사망자 위령과 세계 평화를 기원해 1955년에 완성한 공원. 원폭 돔과 평화기념자료관, 피폭 벽오동 등이 있다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('원폭 돔', '原爆ドーム', 'HISTORIC', '広島県', '広島市中区', 34.395500, 132.453500, 'ALWAYS', NULL, NULL, NULL, '바깥에서 상시 관람 (내부 입장 불가)', '무료', '평화기념공원 안에 있는 유네스코 세계유산.', '평화기념공원과 이어서 돌아보자.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('히로시마 평화기념자료관', '広島平和記念資料館', 'MUSEUM', '広島県', '広島市中区', 34.391500, 132.452600, 'FIXED', '07:30', '19:00', NULL, '3~11월 기준. 8월 20:00(8/5·6은 21:00), 12~2월 18:00. 입관 30분 전 마감. 7:30~8:30과 마지막 1시간은 웹 예약 필요. 12/30·31과 2월 중순 3일 휴관', '200엔 (고교생 100엔, 중학생 이하 무료)', '원폭 피해의 실상을 피폭자 유품과 사진으로 전하는 자료관. 본관은 국가 중요문화재다.', '관람에 3시간쯤 잡는 게 좋고, 혼잡할 땐 웹 티켓이 빠르다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('히로시마성 (니노마루)', '広島城', 'HISTORIC', '広島県', '広島市中区', 34.402700, 132.459300, 'FIXED', '09:00', '17:30', NULL, '4~9월 기준, 10~3월은 16:30까지. 입관 30분 전 마감. 12/29~12/31 휴관. 천수각은 2026년 3월 22일 폐성, 외관만 관람', '니노마루 무료', '모리 데루모토가 1589년에 쌓기 시작한 성. 원폭으로 무너진 뒤 재건한 천수각은 노후로 2026년 3월에 문을 닫았고, 복원한 니노마루 건물은 무료로 볼 수 있다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('이즈모 대사', '出雲大社', 'SHRINE_TEMPLE', '島根県', '出雲市', 35.401800, 132.685500, 'VARIES', NULL, NULL, NULL, '3~10월 6:00~20:00, 11~12월 6:30~20:00 (1~2월 개문 시간 미확인)', '무료', '인연을 맺어 주는 신 오쿠니누시노오카미를 모신 신사. 음력 10월에 전국의 신들이 모인다고 전해져 이즈모에선 이달을 "가미아리즈키"라 부른다.', '참배 예법은 "두 번 절, 네 번 박수, 한 번 절". 배전의 거대한 시메나와는 길이 8m, 무게 1톤이다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('시마네현립 고대 이즈모 역사박물관', '島根県立古代出雲歴史博物館', 'MUSEUM', '島根県', '出雲市', 35.399200, 132.689400, 'FIXED', '09:00', '18:00', NULL, '11~2월은 17:00까지. 입관 30분 전 마감. 매월 셋째 화요일 휴관(공휴일이면 다음 날). 2025년 4월~2026년 9월 보수 휴관이 있었으니 재개관 후 일정은 공식 확인', '상설전 620엔', '이즈모 대사 바로 동쪽의 박물관. 높이 48m였다고 전하는 고대 이즈모 대사 본전의 1/10 모형과 국보 동검·동탁이 볼거리다.', '이즈모 대사까지 걸어서 5분.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('고치성', '高知城', 'HISTORIC', '高知県', '高知市', 33.560700, 133.531500, 'FIXED', '09:00', '17:00', NULL, '천수각 기준, 입관 16:30까지. 12/26~1/1 휴관. 성 둘레 고치 공원은 24시간', '천수각 420엔 (18세 미만 무료)', '천수와 혼마루 어전이 모두 현존하는 유일한 성.', '천수와 오테몬을 한 장의 사진에 담을 수 있는 게 포인트.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('히로메 시장', 'ひろめ市場', 'MARKET', '高知県', '高知市', 33.560800, 133.535700, 'FIXED', '10:00', '23:00', NULL, '일요일은 9:00부터. 라스트오더 22:30. 1·6·10월에 연 6일쯤 휴무, 가게마다 시간이 다름', '무료', '고치 향토요리부터 세계 음식까지 60여 가게가 모인 포장마차 시장.', '많은 가게가 낮부터 열어 점심이나 낮술로 들르기 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('도사 일요시장', '日曜市', 'MARKET', '高知県', '高知市', 33.561800, 133.536200, 'FIXED', '05:30', '16:00', 'MON,TUE,WED,THU,FRI,SAT', '일요일만. 4~9월 5:00~17:00, 10~3월 5:30~16:00. 1/1·1/2와 8/10~8/12 휴장', '무료', '1690년 도사번이 정한 데서 시작된 300년 넘는 거리 시장. 오테스지 약 900m에 노점이 늘어선다.', '일찍 갈수록 채소·과일이 많다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('고치현립 마키노 식물원', '高知県立牧野植物園', 'PARK_GARDEN', '高知県', '高知市', 33.546600, 133.577800, 'FIXED', '09:00', '17:00', NULL, '입장 16:30까지. 연말연시(12/27~1/1)와 월 1회쯤 정비 휴원일', '850엔 (고교생 이하 무료)', '"일본 식물분류학의 아버지" 마키노 도미타로를 기리는 식물원.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('고치현립 사카모토 료마 기념관', '高知県立坂本龍馬記念館', 'MUSEUM', '高知県', '高知市', 33.497300, 133.575000, 'FIXED', '09:00', '17:00', NULL, '입관 16:30까지. 연중무휴 (폭풍우·정비로 임시 휴관 있음). 11/15는 무료 개관', '900엔 (전시 교체 기간 500엔, 고교생 이하 무료)', '사카모토 료마의 생애와 막부 말기 역사를 료마의 친필 편지를 중심으로 소개하는 기념관.', '료마의 생일이자 개관 기념일인 11월 15일은 무료다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('비잔 로프웨이', '眉山ロープウェイ', 'VIEWPOINT', '徳島県', '徳島市', 34.071200, 134.546500, 'FIXED', '09:00', '21:00', NULL, '4~10월 기준, 11~3월은 17:30까지. 겨울(2월쯤) 정기 점검 운휴', NULL, '아와오도리 회관 5층에서 출발해 비잔 산꼭대기까지 약 6분. 정상에서 도쿠시마 평야가 내려다보이고, 맑으면 아와지섬까지 보인다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('아와오도리 회관', '阿波おどり会館', 'MUSEUM', '徳島県', '徳島市', 34.071100, 134.546300, 'VARIES', NULL, NULL, NULL, '공연 시간에 맞춰 운영. 2·6·9·12월 둘째 수요일 휴관(공휴일이면 다음 날)', NULL, '1년 내내 아와오도리를 볼 수 있는 시설. 250석 전용 홀과 아와오도리 박물관, 도쿠시마 특산품 가게가 있다.', '밤 공연에는 유명 연(連)이 날마다 바뀌어 나오고, 관객이 함께 춤추는 체험 코너도 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('마쓰야마성', '松山城', 'HISTORIC', '愛媛県', '松山市', 33.845600, 132.765600, 'FIXED', '09:00', '17:00', NULL, '천수 기준. 8월 17:30, 12~1월 16:30까지. 로프웨이·리프트로 오를 수 있음', '천수 520엔 (로프웨이·리프트 왕복 520엔 별도)', '성 아래 시로야마 공원이 벚꽃 명소인 산 위의 성.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('도고 온천 본관', '道後温泉本館', 'HISTORIC', '愛媛県', '松山市', 33.852000, 132.786400, 'FIXED', '06:00', '23:00', NULL, '입장 22:30까지, 이용 60분. 12월에 하루 임시 휴관', NULL, '마쓰야마의 대표 온천 건물.', '근처 별관 아스카노유와 묶어 즐길 수 있다.', NULL, NULL, DATE '2026-11-22', NULL);
